<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, withBasePath, activeStatuses, dateLabel, modeLabels, runLabels, stageLabels } from '../api';
import { workspace, currentBoard, loadWorkspace } from '../workspace';
import EmptyState from '../components/EmptyState.vue';
import StatusBadge from '../components/StatusBadge.vue';
const route=useRoute();const router=useRouter();
const rules=ref([]), runs=ref([]), profiles=ref([]), activeRun=ref(null), events=ref([]);
const loading=ref(false), busy=ref(''), error=ref(''), streamState=ref('');
const mode=ref('program'), selectedRules=ref([]), concurrency=ref(2), profileId=ref(''), objects=ref(''), query=ref('');
let boardGeneration=0, runGeneration=0, stream=null, timer=null, refreshing=false;
const availableRules=computed(()=>rules.value.filter(rule=>mode.value!=='program'||rule.mode==='program'));
const displayedRules=computed(()=>availableRules.value.filter(rule=>`${rule.id} ${rule.title}`.toLowerCase().includes(query.value.toLowerCase())));
const inFlight=computed(()=>runs.value.find(run=>activeStatuses.has(run.status)));
const active=computed(()=>activeRun.value&&activeStatuses.has(activeRun.value.status));
const needModel=computed(()=>mode.value==='review');
const selectedCount=computed(()=>selectedRules.value.length);
const progressCount=computed(()=>activeRun.value?.progress?.completed ?? activeRun.value?.completed ?? 0);
const progressTotal=computed(()=>activeRun.value?.progress?.total ?? activeRun.value?.total ?? 0);
const errorText=computed(()=>{const value=activeRun.value?.error||activeRun.value?.errors;if(Array.isArray(value))return value.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('\n');return typeof value==='string'?value:value?JSON.stringify(value):'';});
const tone=status=>status==='completed'?'success':status==='failed'?'danger':status==='running'?'info':status==='stopping'?'warning':'neutral';
const stages=['prep','enumerate','program','context_build','judge','aggregate','gate','publish'];
watch(mode,()=>{selectedRules.value=route.query.rule&&availableRules.value.some(r=>r.id===route.query.rule)?[String(route.query.rule)]:availableRules.value.map(r=>r.id);});
function applyScope(){if(['materials','program','review'].includes(route.query.mode))mode.value=route.query.mode;if(route.query.object)objects.value=String(route.query.object);if(route.query.rule&&availableRules.value.some(r=>r.id===route.query.rule))selectedRules.value=[String(route.query.rule)];}
watch(()=>[route.query.mode,route.query.rule,route.query.object],applyScope);
function selectAll(){selectedRules.value=availableRules.value.map(r=>r.id);}
function clearSelection(){selectedRules.value=[];}
function stopWatching(){if(stream)stream.close();stream=null;clearInterval(timer);timer=null;streamState.value='';}
async function refreshRun(){if(!activeRun.value?.id||refreshing)return;const id=activeRun.value.id;refreshing=true;try{const result=await api.run(id);if(activeRun.value?.id!==id)return;activeRun.value=result.run||result;if(Array.isArray(result.events))events.value=result.events;const index=runs.value.findIndex(r=>r.id===id);if(index>=0)runs.value[index]=activeRun.value;if(!activeStatuses.has(activeRun.value.status)){stopWatching();await loadWorkspace();}}catch(e){error.value=e.message;}finally{refreshing=false;}}
function followRun(id){stopWatching();if(!activeStatuses.has(activeRun.value?.status))return;streamState.value='connecting';stream=new EventSource(withBasePath(`/api/runs/${encodeURIComponent(id)}/events`));stream.onopen=()=>{streamState.value='live';};stream.onerror=()=>{streamState.value='reconnecting';};const receive=event=>{try{const row=JSON.parse(event.data);if(row.seq&&!events.value.some(e=>e.seq===row.seq))events.value=[...events.value,row].slice(-200);}catch{/* Refresh remains authoritative. */}refreshRun();};stream.onmessage=receive;for(const name of ['queued','progress','stage','status','completed','failed','stopped','event','log','update','run'])stream.addEventListener(name,receive);timer=setInterval(refreshRun,3000);}
async function showRun(id){const token=++runGeneration;stopWatching();activeRun.value=null;events.value=[];if(!id)return;try{const value=await api.run(id);if(token!==runGeneration)return;activeRun.value=value.run||value;events.value=value.events||[];followRun(activeRun.value.id);}catch(e){if(token===runGeneration)error.value=e.message;}}
async function load(){const id=workspace.boardId;const token=++boardGeneration;stopWatching();runs.value=[];activeRun.value=null;error.value='';if(!id)return;loading.value=true;try{const [rs,rr,pp]=await Promise.all([api.rules(),api.runs(id),api.profiles()]);if(token!==boardGeneration)return;rules.value=(rs.rules||[]).map(r=>({...r,id:r.id||r.rule_id,mode:r.mode==='agent'?'review':r.mode}));runs.value=rr.runs||[];profiles.value=pp.profiles||[];profileId.value=pp.default_profile_id||profiles.value[0]?.id||'';selectedRules.value=availableRules.value.map(r=>r.id);applyScope();const preferred=String(route.query.run||'');const current=runs.value.find(r=>r.id===preferred)||inFlight.value||runs.value[0];if(current)await showRun(current.id);}catch(e){if(token===boardGeneration)error.value=e.message;}finally{if(token===boardGeneration)loading.value=false;}}
watch(()=>workspace.boardId,load,{immediate:true});
watch(()=>route.query.run,id=>{if(id&&id!==activeRun.value?.id)showRun(String(id));});
function chooseRun(run){router.replace({path:'/runs',query:{board:workspace.boardId,run:run.id}});}
async function start(){if(mode.value!=='materials'&&!selectedRules.value.length){error.value='请至少选择一个检查项。';return;}busy.value='start';error.value='';try{const result=await api.createRun(workspace.boardId,{mode:mode.value,rule_ids:mode.value==='materials'?[]:selectedRules.value,objects:objects.value.split(/[，,\s]+/).map(x=>x.trim()).filter(Boolean),concurrency:Number(concurrency.value),profile_id:profileId.value||null,resume:false});const run=result.run||result;runs.value=[run,...runs.value];await showRun(run.id);router.replace({path:'/runs',query:{board:workspace.boardId,run:run.id}});await loadWorkspace();}catch(e){error.value=e.message;}finally{busy.value='';}}
async function act(action){if(!activeRun.value)return;busy.value=action;error.value='';try{const result=await(action==='stop'?api.stopRun(activeRun.value.id):api.resumeRun(activeRun.value.id));const run=result.run||result;if(action==='resume'&&run.id){runs.value=[run,...runs.value];await showRun(run.id);router.replace({path:'/runs',query:{board:workspace.boardId,run:run.id}});}else await refreshRun();}catch(e){error.value=e.message;}finally{busy.value='';}}
function eventText(event){const data=event.data||event.payload||event;return data.message||data.detail||(data.stage?stageLabels[data.stage]||data.stage:'')||(event.type?stageLabels[event.type]||event.type:JSON.stringify(data));}
onBeforeUnmount(()=>{boardGeneration++;runGeneration++;stopWatching();});
</script>
<template>
  <EmptyState v-if="!workspace.boardId&&!workspace.loading" title="先选择一个项目" description="选择板卡后，可以配置评审范围并追踪后台任务。"><router-link class="button primary" to="/">前往项目</router-link></EmptyState>
  <section v-else>
    <div class="page-heading"><div><div class="eyebrow">REVIEW RUNS</div><h1>安排一次评审</h1><p>{{ currentBoard?.name }} · 明确检查范围，执行状态与工程结论分别记录。</p></div><router-link class="button" :to="{path:'/materials',query:{board:workspace.boardId}}">查看材料</router-link></div>
    <div v-if="error" class="notice error" role="alert">{{ error }}</div>
    <div v-if="loading" class="loading-state">正在加载检查范围与任务</div>
    <div v-else class="run-layout">
      <form class="section-card run-settings" @submit.prevent="start"><div class="section-heading"><h2>新建运行</h2></div><fieldset class="mode-options"><legend class="sr-only">执行模式</legend><label v-for="(label,key) in modeLabels" :key="key" :class="{selected:mode===key}"><input type="radio" v-model="mode" :value="key" name="run-mode" /><span>{{ label }}<small>{{ key==='materials'?'核对材料与连接事实':key==='program'?'执行可重复的程序规则':'通过模型分析对象与证据' }}</small></span></label></fieldset>
        <div v-if="needModel&&!profiles.length" class="notice warning">尚未配置模型服务。<router-link to="/models">前往模型设置</router-link></div>
        <template v-if="mode!=='materials'"><div class="section-heading rule-heading"><h3>检查范围 <span class="muted">{{ selectedCount }} 项</span></h3><div class="actions"><button class="table-action" type="button" @click="selectAll">全选</button><button class="table-action" type="button" @click="clearSelection">清空</button></div></div><label class="sr-only" for="rule-search">搜索检查项</label><input id="rule-search" class="search-input" v-model="query" placeholder="搜索检查项或编号" /><div class="rule-options"><label v-for="rule in displayedRules" :key="rule.id" class="rule-option"><input type="checkbox" v-model="selectedRules" :value="rule.id" /><span><strong>{{ rule.id }}</strong>{{ rule.title }}</span><small>{{ rule.mode==='program'?'程序':'LLM' }}</small></label><p v-if="!displayedRules.length" class="small-copy muted">没有匹配的检查项。</p></div></template>
        <div v-if="mode!=='materials'" class="field model-picker"><label for="run-profile">模型配置</label><select id="run-profile" v-model="profileId"><option value="">{{ needModel?'请选择模型配置':'不使用模型配置' }}</option><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{ profile.name || profile.model }} · {{ profile.model }}</option></select><span class="help">{{ needModel?'用于本次评审与文案生成。':'程序判定由本机执行；需要模型生成报告文案时使用此配置。' }}</span></div>
        <details class="run-advanced"><summary>高级设置</summary><div class="field"><label for="run-concurrency">对象并发数</label><input id="run-concurrency" v-model="concurrency" type="number" min="1" max="8" /></div><div v-if="mode==='review'" class="field"><label for="run-objects">限定对象（可选）</label><input id="run-objects" v-model="objects" placeholder="例如 R1, R2；留空检查适用对象" /><span class="help">后端会验证对象是否属于所选规则的适用范围。</span></div></details>
        <div v-if="inFlight" class="notice">本项目有任务{{ runLabels[inFlight.status] || '运行中' }}，完成或停止后可以创建新运行。</div><button class="button primary run-start" :disabled="!!busy||!!inFlight||(needModel&&!profileId)||(mode!=='materials'&&!selectedCount)">{{ busy==='start'?'正在创建任务…':mode==='materials'?'开始材料检查':'开始评审' }}</button><p class="inline-note">任务由本机后台执行，关闭或刷新页面后仍可回到这里查看。</p>
      </form>
      <div class="run-monitor"><div v-if="!activeRun" class="section-card"><EmptyState title="准备好后，开始第一次运行" description="选择左侧的模式和检查范围。运行开始后，这里显示真实阶段、事件和结果。" /></div><div v-else class="section-card"><div class="section-heading"><h2>运行详情</h2><StatusBadge :tone="tone(activeRun.status)">{{ runLabels[activeRun.status] || activeRun.status }}</StatusBadge></div><div class="run-ident"><strong>{{ modeLabels[activeRun.mode]||'评审任务' }}</strong><span class="mono">{{ activeRun.id?.slice(0,12) }}</span></div><div class="current-stage"><span>当前阶段</span><strong>{{ stageLabels[activeRun.stage] || activeRun.stage || (activeRun.status==='queued'?'等待调度':'—') }}</strong><small v-if="progressTotal>0">对象进度 {{ progressCount }} / {{ progressTotal }}</small><small v-else-if="active">正在确定阶段范围</small></div><progress v-if="progressTotal>0" :value="progressCount" :max="progressTotal" :aria-label="`对象进度 ${progressCount}/${progressTotal}`"></progress><div class="run-stage-track"><span v-for="stage in stages" :key="stage" :class="{current:activeRun.stage===stage}">{{ stageLabels[stage] }}</span></div><dl class="metadata-list"><div><dt>开始时间</dt><dd>{{ dateLabel(activeRun.started_at||activeRun.created_at) }}</dd></div><div v-if="activeRun.finished_at"><dt>结束时间</dt><dd>{{ dateLabel(activeRun.finished_at) }}</dd></div><div><dt>检查范围</dt><dd>{{ (activeRun.rule_ids||[]).join('、') || (activeRun.mode==='materials'?'材料准备':'全部适用规则') }}</dd></div><div v-if="activeRun.parent_id"><dt>续跑来源</dt><dd class="mono">{{ activeRun.parent_id.slice(0,12) }}</dd></div></dl><div v-if="errorText" class="notice error run-error" role="alert">{{ errorText }}</div><div v-if="activeRun.status==='completed'" class="notice success">执行已完成。工程判定以报告中的对象结论为准。</div><div class="actions run-actions"><button v-if="active" class="button danger" :disabled="!!busy||activeRun.status==='stopping'" @click="act('stop')">{{ busy==='stop'||activeRun.status==='stopping'?'正在停止…':'停止运行' }}</button><button v-if="['stopped','interrupted','failed'].includes(activeRun.status)" class="button" :disabled="!!busy||!!inFlight" @click="act('resume')">{{ busy==='resume'?'创建续跑…':'从有效结果续跑' }}</button><router-link v-if="activeRun.report_url||activeRun.report_dir" class="button primary" :to="{path:'/reports',query:{board:workspace.boardId,run:activeRun.id}}">打开评审报告 →</router-link><button class="button ghost" :disabled="!!busy" @click="refreshRun">刷新状态</button></div></div>
      <div v-if="activeRun" class="section-card"><div class="section-heading"><h2>运行事件</h2><span v-if="active" role="status">{{ streamState==='live'?'实时连接':streamState==='reconnecting'?'重连中 · 自动刷新':'正在连接事件流' }}</span></div><ol v-if="events.length" class="event-list"><li v-for="(event,index) in events.slice(-50).reverse()" :key="event.seq||index"><time>{{ dateLabel(event.created_at||event.ts) }}</time><span>{{ eventText(event) }}</span></li></ol><p v-else class="small-copy muted">尚无运行事件。任务开始后会显示阶段与交付记录。</p></div></div>
    </div>
    <div v-if="runs.length" class="section-card history-table"><div class="section-heading"><h2>运行记录</h2><span>{{ runs.length }} 次</span></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>批次</th><th>模式</th><th>创建时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td class="mono">{{ run.id?.slice(0,12) }}</td><td>{{ modeLabels[run.mode]||run.mode }}</td><td>{{ dateLabel(run.created_at) }}</td><td><StatusBadge :tone="tone(run.status)">{{ runLabels[run.status]||run.status }}</StatusBadge></td><td><button class="table-action" @click="chooseRun(run)">查看运行</button></td></tr></tbody></table></div></div>
  </section>
</template>
<style scoped>
.run-layout{display:grid;grid-template-columns:minmax(360px,440px) minmax(0,1fr);gap:24px;align-items:start}.run-settings{padding:24px}.mode-options{border:0;margin:0 0 22px;padding:0;display:grid;gap:9px}.mode-options label{display:flex;gap:12px;align-items:center;padding:13px 14px;border:1px solid #dce6df;border-radius:8px;cursor:pointer;font-size:14px}.mode-options label.selected{border-color:#78ac96;background:#f0f8f3}.mode-options input{accent-color:var(--wb-teal);width:16px;height:16px}.mode-options span{font-weight:600}.mode-options small{display:block;font-size:12px;font-weight:400;color:#698075;margin-top:4px}.rule-heading h3{font-size:14px}.rule-heading h3 span{font-size:12px;margin-left:6px;font-weight:400}.rule-options{max-height:290px;overflow:auto;margin-top:9px;border-bottom:1px solid #e4eae5;padding-bottom:10px}.rule-option{display:flex;gap:9px;align-items:flex-start;padding:11px 2px;font-size:12px;line-height:1.6;cursor:pointer}.rule-option input{accent-color:var(--wb-teal);width:15px;height:15px;flex-shrink:0;margin-top:2px}.rule-option span{flex:1}.rule-option strong{display:block;font-family:ui-monospace,monospace;font-size:11px;color:#427464;font-weight:500}.rule-option small{font-size:10px;color:#6d8277;flex-shrink:0;padding-top:2px}.model-picker{margin-top:22px}.run-advanced{margin:20px 0}.run-advanced summary{font-size:13px;color:#556f62;cursor:pointer;margin-bottom:16px}.run-start{width:100%}.run-ident{display:flex;justify-content:space-between;gap:12px;margin:24px 0;font-size:14px}.run-ident span{font-size:11px;color:#7a8d82}.current-stage{display:flex;flex-direction:column;gap:10px;padding:20px 23px;background:#f0f7f3;border:1px solid #dceadf;border-radius:9px}.current-stage>span{font-size:12px;color:#5d7b69}.current-stage strong{font-size:23px;font-weight:550;color:#235c45}.current-stage small{color:#587964}.run-stage-track{display:flex;flex-wrap:wrap;gap:7px;margin:20px 0 25px}.run-stage-track span{padding:4px 7px;border-radius:4px;font-size:11px;color:#819087;background:#f4f6f4}.run-stage-track span.current{background:#dceee2;color:#2c7352;font-weight:600}.run-monitor progress{width:100%;height:7px;border:0;border-radius:3px;overflow:hidden;margin-top:12px;accent-color:var(--wb-teal)}.run-monitor progress::-webkit-progress-bar{background:#e8eeea}.run-monitor progress::-webkit-progress-value{background:var(--wb-teal)}.run-actions{margin-top:25px;padding-top:20px;border-top:1px solid #e4ebe6}.run-error{white-space:pre-wrap;margin-top:20px}.event-list{list-style:none;padding:0;margin:0;max-height:330px;overflow:auto}.event-list li{display:flex;gap:20px;font-size:12px;line-height:1.65;padding:11px 0;border-bottom:1px solid #edf1ed}.event-list li:last-child{border-bottom:0}.event-list time{font-family:ui-monospace,monospace;font-size:11px;color:#73887c;min-width:145px;flex-shrink:0}.event-list span{overflow-wrap:anywhere}.history-table{margin-top:6px}@media(max-width:960px){.run-layout{grid-template-columns:1fr}.run-monitor{grid-row:1}.run-monitor:has(.empty-state){grid-row:auto}.run-settings{padding:20px}.event-list li{flex-direction:column;gap:4px}.event-list time{min-width:0}}
</style>
